(function (window, document) {
  if (window.tinymce) {
    return;
  }

  var editors = {};
  var onceHandlers = { AddEditor: [] };

  function toNodeList(selector) {
    if (!selector) return [];
    if (selector.charAt(0) === '#') {
      var node = document.getElementById(selector.slice(1));
      return node ? [node] : [];
    }
    return Array.prototype.slice.call(document.querySelectorAll(selector));
  }

  function createEditor(element, initOptions) {
    var handlers = {};

    function emit(eventName) {
      (handlers[eventName] || []).forEach(function (cb) {
        cb();
      });
    }

    var editor = {
      id: element.id,
      getContent: function () {
        return element.value || '';
      },
      setContent: function (html) {
        element.value = html || '';
      },
      on: function (eventNames, cb) {
        (eventNames || '').split(/\s+/).filter(Boolean).forEach(function (name) {
          handlers[name] = handlers[name] || [];
          handlers[name].push(cb);
        });
      },
      remove: function () {
        delete editors[element.id];
      }
    };

    ['input', 'change', 'keyup'].forEach(function (domEvent) {
      element.addEventListener(domEvent, function () {
        emit('change');
        emit('keyup');
      });
    });

    if (typeof initOptions.setup === 'function') {
      initOptions.setup(editor);
    }

    return editor;
  }

  window.tinymce = {
    init: function (options) {
      var targets = toNodeList(options && options.selector);
      targets.forEach(function (target) {
        if (!target.id) return;
        if (editors[target.id]) return;

        var editor = createEditor(target, options || {});
        editors[target.id] = editor;

        var pending = onceHandlers.AddEditor.splice(0, onceHandlers.AddEditor.length);
        pending.forEach(function (cb) {
          cb({ editor: editor });
        });
      });
    },
    get: function (id) {
      return editors[id] || null;
    },
    once: function (eventName, cb) {
      if (!onceHandlers[eventName]) {
        onceHandlers[eventName] = [];
      }
      onceHandlers[eventName].push(cb);
    }
  };
})(window, document);
